// Web sıcaklık panosu: DHT22 ölçer, ESP32 web sayfasında canlı gösterir.
#include <WiFi.h>
#include <WebServer.h>
#include <DHT.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const int DHT_PIN = 4;
const unsigned long OLCUM_ARASI_MS = 2000;  // DHT22 en sık 2 sn'de bir okunur

WebServer sunucu(80);
DHT dht(DHT_PIN, DHT22);
float sicaklik = NAN, nem = NAN;
// Açılıştan beri en düşük ve en yüksek değerler.
float enAzS = NAN, enCokS = NAN, enAzN = NAN, enCokN = NAN;
unsigned long sonOlcum = 0;
bool ilkOlcum = true;

// Sayfa her 2 sn'de /veri adresinden JSON çeker ve çubukları günceller.
const char SAYFA[] PROGMEM = R"HTML(<!doctype html>
<html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Sıcaklık panosu</title>
<style>
body{font-family:sans-serif;max-width:420px;margin:auto;padding:16px}
.kart{border:1px solid #ccc;border-radius:12px;padding:12px 16px;margin:12px 0}
.deger{font-size:40px;font-weight:bold}
.cubuk{height:14px;background:#eee;border-radius:7px;overflow:hidden;margin:8px 0}
.dolu{height:100%;width:0;transition:width .5s}
.kucuk{color:#555;font-size:14px}
</style></head><body>
<h1>Sıcaklık panosu</h1>
<div class="kart">Sıcaklık<div class="deger" id="s">--</div>
<div class="cubuk"><div class="dolu" id="sc" style="background:#ea580c"></div></div>
<div class="kucuk">En düşük <b id="sa">--</b> · En yüksek <b id="sy">--</b></div></div>
<div class="kart">Nem<div class="deger" id="n">--</div>
<div class="cubuk"><div class="dolu" id="nc" style="background:#2563eb"></div></div>
<div class="kucuk">En düşük <b id="na">--</b> · En yüksek <b id="ny">--</b></div></div>
<p class="kucuk" id="durum">Bekleniyor...</p>
<script>
var yaz = function (id, v, birim) { document.getElementById(id).textContent = v === null ? '--' : v.toFixed(1) + birim; };
var cubuk = function (id, oran) { document.getElementById(id).style.width = Math.max(0, Math.min(100, oran)) + '%'; };
var yenile = function () {
  fetch('/veri').then(function (r) { return r.json(); }).then(function (d) {
    yaz('s', d.sicaklik, ' °C'); yaz('sa', d.enAzS, ' °C'); yaz('sy', d.enCokS, ' °C');
    yaz('n', d.nem, ' %'); yaz('na', d.enAzN, ' %'); yaz('ny', d.enCokN, ' %');
    cubuk('sc', d.sicaklik === null ? 0 : d.sicaklik * 2);   // 0-50 °C -> %0-100
    cubuk('nc', d.nem === null ? 0 : d.nem);
    document.getElementById('durum').textContent = d.sicaklik === null
      ? 'Sensör okunamadı. Kabloları kontrol et.'
      : 'Son güncelleme: çalışma süresi ' + d.sure + ' sn';
  }).catch(function () { document.getElementById('durum').textContent = 'ESP32 cevap vermedi.'; });
};
yenile();
setInterval(yenile, 2000);
</script></body></html>)HTML";

void olc() {
  float s = dht.readTemperature();
  float n = dht.readHumidity();
  if (isnan(s) || isnan(n)) {
    Serial.println("DHT22 okunamadi.");
    sicaklik = NAN;
    nem = NAN;
    return;
  }
  sicaklik = s;
  nem = n;
  if (isnan(enAzS) || s < enAzS) enAzS = s;
  if (isnan(enCokS) || s > enCokS) enCokS = s;
  if (isnan(enAzN) || n < enAzN) enAzN = n;
  if (isnan(enCokN) || n > enCokN) enCokN = n;
  Serial.printf("Sicaklik: %.1f C  Nem: %.0f %%\n", s, n);
}

// Ölçüm yoksa JSON'a null yaz.
String sayi(float v) {
  return isnan(v) ? String("null") : String(v, 1);
}

void anaSayfa() {
  sunucu.send(200, "text/html", SAYFA);
}

void veri() {
  String j = "{\"sicaklik\":";
  j += sayi(sicaklik);
  j += ",\"nem\":";
  j += sayi(nem);
  j += ",\"enAzS\":";
  j += sayi(enAzS);
  j += ",\"enCokS\":";
  j += sayi(enCokS);
  j += ",\"enAzN\":";
  j += sayi(enAzN);
  j += ",\"enCokN\":";
  j += sayi(enCokN);
  j += ",\"sure\":";
  j += millis() / 1000;
  j += "}";
  sunucu.send(200, "application/json", j);
}

void setup() {
  Serial.begin(115200);
  dht.begin();

  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  Serial.print("Wi-Fi'ye baglaniyor");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Baglandi. Tarayicida ac: http://");
  Serial.println(WiFi.localIP());

  sunucu.on("/", anaSayfa);
  sunucu.on("/veri", veri);
  sunucu.begin();
}

void loop() {
  sunucu.handleClient();
  // delay() yerine millis(): ölçüm beklerken sunucu cevap vermeye devam eder.
  if (ilkOlcum || millis() - sonOlcum >= OLCUM_ARASI_MS) {
    ilkOlcum = false;
    sonOlcum = millis();
    olc();
  }
}
